import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[] sl = new int[51];
        sl[0] = 1;
        for (int i = 1; i <= 50; i++) {
            sl[i] = sl[i - 1] + (1 << i); // 2^i
        }

        int h = sc.nextInt();
        int n = sc.nextInt();

        n += sl[h - 1];

        int[] nl = new int[1000]; // arbitrary size, should be enough
        int nlSize = 0;
        nl[nlSize++] = n;

        while (n != 1) {
            n /= 2;
            nl[nlSize++] = n;
        }

        int ans = 0;
        int cn = 1;
        boolean cp = false;

        while (cn != nl[0]) {
            int[] tnl = new int[h + 2]; // size h+2 to avoid index issues
            int tnlIndex = 0;
            int current = cn;
            for (int i = 0; i < h; i++) {
                tnl[tnlIndex++] = current;
                if (!cp) {
                    current *= 2;
                } else {
                    current = current * 2 + 1;
                }
                cp = !cp;
            }
            if (current == nl[0]) {
                ans += h;
                break;
            }
            tnl[tnlIndex++] = current;
            // reverse tnl
            for (int i = 0; i < tnlIndex / 2; i++) {
                int temp = tnl[i];
                tnl[i] = tnl[tnlIndex - i - 1];
                tnl[tnlIndex - i - 1] = temp;
            }
            boolean found = false;
            for (int i = 1; i <= h; i++) {
                if (nl[i] == tnl[i]) {
                    ans += sl[i - 1] + h - i + 1;
                    h = i - 1;
                    cn = tnl[i - 1];
                    if (cn == tnl[i] * 2) {
                        cn = tnl[i] * 2 + 1;
                        cp = false;
                    } else {
                        cn = tnl[i] * 2;
                        cp = true;
                    }
                    found = true;
                    break;
                }
            }
            if (!found) {
                // If no match found, break to prevent infinite loop
                break;
            }
        }
        System.out.println(ans);
        sc.close();
    }
}
